58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final OwnerFieldsValidator ownerFieldsValidator;
76	
77	    private final PostcodeValidator postcodeValidator;
78	
79	    private final TelephoneNormalizer telephoneNormalizer;
80	
81	    private final EmailNormalizer emailNormalizer;
82	
83	    private final AddressNormalizer addressNormalizer;
84	
85	    private final BusinessDayResolver businessDayResolver;
86	
87	    private final OwnerAuditLogger ownerAuditLogger;
88	
89	    /** Maximum number of owners a single city may hold before further creations are rejected. */
90	    static final long MAX_OWNERS_PER_CITY = 50;
91	
92	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
93	    static final long MAX_OWNERS_PER_DAY = 100;
94	
95	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
96	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper,
102	                                 OwnerFieldsValidator ownerFieldsValidator,
103	                                 PostcodeValidator postcodeValidator,
104	                                 TelephoneNormalizer telephoneNormalizer,
105	                                 EmailNormalizer emailNormalizer,
106	                                 AddressNormalizer addressNormalizer,
107	                                 BusinessDayResolver businessDayResolver,
108	                                 OwnerAuditLogger ownerAuditLogger) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	        this.ownerFieldsValidator = ownerFieldsValidator;
114	        this.postcodeValidator = postcodeValidator;
115	        this.telephoneNormalizer = telephoneNormalizer;
116	        this.emailNormalizer = emailNormalizer;
117	        this.addressNormalizer = addressNormalizer;
118	        this.businessDayResolver = businessDayResolver;
119	        this.ownerAuditLogger = ownerAuditLogger;
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
125	        Collection<Owner> owners;
126	        if (lastName != null) {
127	            owners = this.clinicService.findOwnerByLastName(lastName);
128	        } else {
129	            owners = this.clinicService.findAllOwners();
130	        }
131	        if (owners.isEmpty()) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
151	        this.ownerFieldsValidator.validate(ownerFieldsDto);
152	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
156	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
157	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
158	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
159	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
160	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
161	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
162	        }
163	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
164	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
165	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
166	        }
167	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
168	            this.clinicService.joinHousehold(owner);
169	        }
170	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
171	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
172	        }
173	        this.clinicService.saveOwner(owner);
174	        this.ownerAuditLogger.logCreated(owner);
175	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
184	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
185	        if (currentOwner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        currentOwner.setAddress(ownerFieldsDto.getAddress());
189	        currentOwner.setCity(ownerFieldsDto.getCity());
190	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
191	        currentOwner.setLastName(ownerFieldsDto.getLastName());
192	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
193	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
194	        this.clinicService.saveOwner(currentOwner);
195	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Transactional
200	    @Override
201	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
202	        Owner owner = this.clinicService.findOwnerById(ownerId);
203	        if (owner == null) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        this.clinicService.deleteOwner(owner);
207	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        HttpHeaders headers = new HttpHeaders();
218	        Pet pet = petMapper.toPet(petFieldsDto);
219	        owner.setId(ownerId);
220	        pet.setOwner(owner);
221	        pet.getType().setName(null);
222	        this.clinicService.savePet(pet);
223	        PetDto petDto = petMapper.toPetDto(pet);
224	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
225	            .buildAndExpand(pet.getId()).toUri());
226	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
227	    }
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
232	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
233	        if (currentOwner != null) {
234	            Pet currentPet = this.clinicService.findPetById(petId);
235	            if (currentPet != null) {
236	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
237	                currentPet.setName(petFieldsDto.getName());
238	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
239	                this.clinicService.savePet(currentPet);
240	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
241	            }
242	        }
243	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	    }
245	
246	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
247	    @Override
248	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
249	        HttpHeaders headers = new HttpHeaders();
250	        Visit visit = visitMapper.toVisit(visitFieldsDto);
251	        Pet pet = new Pet();
252	        pet.setId(petId);
253	        visit.setPet(pet);
254	        this.clinicService.saveVisit(visit);
255	        VisitDto visitDto = visitMapper.toVisitDto(visit);
256	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
257	            .buildAndExpand(visit.getId()).toUri());
258	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
259	    }
260	
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Override
264	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
265	        Owner owner = this.clinicService.findOwnerById(ownerId);
266	        if (owner != null) {
267	            Pet pet = owner.getPet(petId);
268	            if (pet != null) {
269	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
270	            }
271	        }
272	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
273	    }
274	}
