16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "membership_number")
67	    private String membershipNumber;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "postcode")
76	    private String postcode;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    public String getTelephone() {
98	        return this.telephone;
99	    }
100	
101	    public void setTelephone(String telephone) {
102	        this.telephone = telephone;
103	    }
104	
105	    public String getEmail() {
106	        return this.email;
107	    }
108	
109	    public void setEmail(String email) {
110	        this.email = email;
111	    }
112	
113	    public LocalDate getRegistrationDate() {
114	        return this.registrationDate;
115	    }
116	
117	    public void setRegistrationDate(LocalDate registrationDate) {
118	        this.registrationDate = registrationDate;
119	    }
120	
121	    public String getCustomerCode() {
122	        return this.customerCode;
123	    }
124	
125	    public void setCustomerCode(String customerCode) {
126	        this.customerCode = customerCode;
127	    }
128	
129	    public String getHouseholdId() {
130	        return this.householdId;
131	    }
132	
133	    public void setHouseholdId(String householdId) {
134	        this.householdId = householdId;
135	    }
136	
137	    public Integer getNamesakeCount() {
138	        return this.namesakeCount;
139	    }
140	
141	    public void setNamesakeCount(Integer namesakeCount) {
142	        this.namesakeCount = namesakeCount;
143	    }
144	
145	    public String getMembershipNumber() {
146	        return this.membershipNumber;
147	    }
148	
149	    public void setMembershipNumber(String membershipNumber) {
150	        this.membershipNumber = membershipNumber;
151	    }
152	
153	    /**
154	     * Whether this owner was created after more than 80 owners had already been registered on the
155	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
156	     */
157	    public Boolean getBulkSignupWarning() {
158	        return this.bulkSignupWarning;
159	    }
160	
161	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
162	        this.bulkSignupWarning = bulkSignupWarning;
163	    }
164	
165	    /**
166	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
167	     * counting this owner) captured once at creation.
168	     */
169	    public Integer getHouseholdSize() {
170	        return this.householdSize;
171	    }
172	
173	    public void setHouseholdSize(Integer householdSize) {
174	        this.householdSize = householdSize;
175	    }
176	
177	    /**
178	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
179	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
180	     */
181	    public String getPostcode() {
182	        return this.postcode;
183	    }
184	
185	    public void setPostcode(String postcode) {
186	        this.postcode = postcode;
187	    }
188	
189	    /**
190	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
191	     */
192	    @Transient
193	    public String getDisplayName() {
194	        return this.getLastName() + ", " + this.getFirstName();
195	    }
196	
197	    /**
198	     * Return this owner's initials as the upper-cased first letters of the first and last
199	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
200	     */
201	    @Transient
202	    public String getInitials() {
203	        return initial(this.getFirstName()) + initial(this.getLastName());
204	    }
205	
206	    private static String initial(String name) {
207	        return Character.toUpperCase(name.charAt(0)) + ".";
208	    }
209	
210	    /** The membership level every owner starts at on creation. */
211	    private static final int BASE_MEMBERSHIP_LEVEL = 1;
212	
213	    /** The highest membership level derivable at creation; level 4 is reserved for tenure. */
214	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
215	
216	    /**
217	     * Return this owner's membership level, a number from 1 to 3 derived at creation: every owner
218	     * starts at {@value #BASE_MEMBERSHIP_LEVEL}; add 1 when an email address is present; add 1 when
219	     * the owner has no namesakes ({@code namesakeCount} is 0); capped at
220	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
221	     */
222	    @Transient
223	    public Integer getMembershipLevel() {
224	        int level = BASE_MEMBERSHIP_LEVEL;
225	        if (hasEmail()) {
226	            level++;
227	        }
228	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
229	            level++;
230	        }
231	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
232	    }
233	
234	    /** Whether this owner has a usable email address (present and not blank). */
235	    private boolean hasEmail() {
236	        return this.email != null && !this.email.isBlank();
237	    }
238	
239	    /**
240	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
241	     * present, otherwise {@code "PHONE"}.
242	     */
243	    @Transient
244	    public String getContactPreference() {
245	        return hasEmail() ? "EMAIL" : "PHONE";
246	    }
247	
248	    /**
249	     * Return this owner's locality: the canonical region derived by preferring the postcode (matched
250	     * against the known region ranges) and falling back to the city-to-region table when the postcode
251	     * is absent or in no known range, or {@code "UNKNOWN"} when neither yields a region.
252	     */
253	    @Transient
254	    public String getLocality() {
255	        return LocalityResolver.regionFor(this.postcode, this.city);
256	    }
257	
258	    /**
259	     * Return this owner's identity key, the single derived value all duplicate detection is based
260	     * on: the normalized telephone, email and household id joined with {@code '|'} as
261	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
262	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
263	     * because the telephone is part of the key, members of one household (same {@code householdId})
264	     * with different telephones have distinct keys and are not duplicates.
265	     */
266	    @Transient
267	    public String getIdentityKey() {
268	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
269	    }
270	
271	    private static String keyPart(String value) {
272	        return value == null ? "" : value;
273	    }
274	
275	    protected Set<Pet> getPetsInternal() {
276	        if (this.pets == null) {
277	            this.pets = new HashSet<>();
278	        }
279	        return this.pets;
280	    }
281	
282	    protected void setPetsInternal(Set<Pet> pets) {
283	        this.pets = pets;
284	    }
285	
286	    public List<Pet> getPets() {
287	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
288	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
289	        return Collections.unmodifiableList(sortedPets);
290	    }
291	
