246	    @Override
247	    @Transactional
248	    public void saveOwner(Owner owner) throws DataAccessException {
249	        if (owner.isNew() && owner.getCustomerCode() == null) {
250	            long sequence = countOwnersInCity(owner.getCity()) + 1L;
251	            owner.setCustomerCode(
252	                customerCodeGenerator.generate(owner.getCity(), owner.getLastName(), sequence));
253	        }
254	        if (owner.isNew() && owner.getNamesakeCount() == null) {
255	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
256	        }
257	        if (owner.isNew() && owner.getMembershipNumber() == null) {
258	            owner.setMembershipNumber(
259	                membershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
260	        }
261	        if (owner.isNew() && owner.getHouseholdSize() == null) {
262	            owner.setHouseholdSize(countHouseholdMembers(owner));
263	        }
264	        ownerRepository.save(owner);
265	    }
266	
267	    /**
268	     * Count the members of the given (not yet persisted) owner's household: the already stored
269	     * owners sharing its {@code householdId} plus the owner itself. An owner with no household
270	     * ({@code householdId} is null) is a household of one. Used to capture an owner's household
271	     * size at creation time.
272	     */
273	    private int countHouseholdMembers(Owner owner) {
274	        String householdId = owner.getHouseholdId();
275	        if (householdId == null) {
276	            return 1;
277	        }
278	        long existing = ownerRepository.findAll().stream()
279	            .filter(existingOwner -> householdId.equals(existingOwner.getHouseholdId()))
280	            .count();
281	        return (int) (existing + 1);
282	    }
283	
284	    /**
285	     * Count the owners already stored in the given city, compared case-insensitively. Used to
286	     * derive the per-city sequence embedded in a new owner's customer code and to enforce the
287	     * per-city capacity limit at creation time.
288	     */
289	    @Override
290	    @Transactional(readOnly = true)
291	    public long countOwnersInCity(String city) throws DataAccessException {
292	        return ownerRepository.findAll().stream()
293	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
294	            .count();
295	    }
296	
297	    /**
298	     * Count the owners already stored whose registration date equals the given date. Used to
299	     * enforce the per-day registration limit at creation time.
300	     */
301	    @Override
302	    @Transactional(readOnly = true)
303	    public long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException {
304	        return ownerRepository.findAll().stream()
305	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
306	            .count();
307	    }
308	
309	    /**
310	     * Count the owners already stored that share the given first and last name, compared
311	     * case-insensitively. Used to capture an owner's namesake count at creation time.
312	     */
313	    private int countNamesakes(String firstName, String lastName) {
314	        return (int) ownerRepository.findAll().stream()
315	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
316	                && equalsIgnoreCase(existing.getLastName(), lastName))
317	            .count();
318	    }
319	
320	    private static boolean equalsIgnoreCase(String a, String b) {
321	        return a != null && a.equalsIgnoreCase(b);
322	    }
