343	    @Override
344	    @Transactional(readOnly = true)
345	    public Collection<Owner> findOwnersInSameHousehold(String lastName, String address) throws DataAccessException {
346	        String targetLastName = householdNormalizer.normalize(lastName);
347	        String targetAddress = householdNormalizer.normalize(address);
348	        return ownerRepository.findAll().stream()
349	            .filter(owner -> householdNormalizer.normalize(owner.getLastName()).equals(targetLastName)
350	                && householdNormalizer.normalize(owner.getAddress()).equals(targetAddress))
351	            .toList();
352	    }
353	
354	    @Override
355	    @Transactional
356	    public String joinHousehold(Owner owner) throws DataAccessException {
357	        Collection<Owner> members = findOwnersInSameHousehold(owner.getLastName(), owner.getAddress());
358	        if (members.isEmpty()) {
359	            return null;
360	        }
361	        String householdId = members.stream()
362	            .map(Owner::getHouseholdId)
363	            .filter(Objects::nonNull)
364	            .findFirst()
365	            .orElseGet(() -> householdIdGenerator.generate(owner.getLastName(), owner.getAddress()));
366	        for (Owner member : members) {
367	            if (!householdId.equals(member.getHouseholdId())) {
368	                member.setHouseholdId(householdId);
369	                ownerRepository.save(member);
370	            }
371	        }
372	        owner.setHouseholdId(householdId);
373	        return householdId;
374	    }
