17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.stereotype.Component;
20	
21	/**
22	 * Normalizes an owner's telephone number into E.164 form on create.
23	 *
24	 * <p>Spaces, dashes and brackets are stripped. A leading {@code +} and its country code
25	 * are kept as-is; without one, the default country code {@code +61} is assumed and a
26	 * single leading {@code 0} is dropped from the national digits. The result must carry
27	 * between 8 and 15 digits after the {@code +}, and for a {@linkplain E164CountryCode
28	 * recognized country code} the national number must have exactly the length that country
29	 * requires (e.g. {@code +61} needs 9 national digits, {@code +1} needs 10). This E.164
30	 * string is what gets stored, returned, and compared when detecting duplicate telephones.
31	 */
32	@Component
33	public class TelephoneNormalizer {
34	
35	    private static final String DEFAULT_COUNTRY_CODE = "61";
36	
37	    private static final int MIN_DIGITS = 8;
38	
39	    private static final int MAX_DIGITS = 15;
40	
41	    /**
42	     * Converts {@code raw} into its E.164 representation.
43	     *
44	     * @param raw the submitted telephone value
45	     * @return the normalized E.164 telephone number (a leading {@code +} followed by digits)
46	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
47	     */
48	    public String normalize(String raw) {
49	        String trimmed = raw == null ? "" : raw.strip();
50	        boolean explicitCountryCode = trimmed.startsWith("+");
51	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
52	
53	        String digits;
54	        if (explicitCountryCode) {
55	            digits = stripped.substring(1);
56	        } else {
57	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
58	            digits = DEFAULT_COUNTRY_CODE + national;
59	        }
60	
61	        if (!digits.matches("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}")) {
62	            throw new InvalidTelephoneException(raw);
63	        }
64	        E164CountryCode.forE164Digits(digits).ifPresent(country -> {
65	            String national = digits.substring(country.callingCode().length());
66	            if (!country.acceptsNationalNumber(national)) {
67	                throw new InvalidTelephoneException(raw);
68	            }
69	        });
70	        return "+" + digits;
71	    }
72	}
