21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Normalizes an owner's optional email address on create/update.
26	 *
27	 * <p>The email is optional: a {@code null} or blank value is treated as absent and left
28	 * unset. When a value is present it must be a syntactically valid address; it is then
29	 * stored and returned lower-cased.
30	 */
31	@Component
32	public class EmailNormalizer {
33	
34	    /**
35	     * A pragmatic syntactic check: a non-empty local part, a single {@code @}, and a
36	     * domain containing at least one dot, none of the segments holding whitespace.
37	     */
38	    private static final Pattern EMAIL_PATTERN =
39	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
40	
41	    /**
42	     * Normalizes an optional email address.
43	     *
44	     * @param raw the submitted email value, possibly {@code null} or blank
45	     * @return the lower-cased email, or {@code null} when no value was supplied
46	     * @throws InvalidEmailException if a value is present but not a valid address
47	     */
48	    public String normalize(String raw) {
49	        if (raw == null || raw.isBlank()) {
50	            return null;
51	        }
52	        String trimmed = raw.trim();
53	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
54	            throw new InvalidEmailException(raw);
55	        }
56	        return trimmed.toLowerCase(Locale.ROOT);
57	    }
58	}
