25	/**
26	 * Resolves a date to the business day on which it takes effect.
27	 *
28	 * <p>A Saturday or Sunday is rolled forward to the following Monday; any weekday is
29	 * returned unchanged. This is applied to an owner's effective registration date so that
30	 * everything derived from it (the stored {@code registrationDate}, the membership
31	 * number's year segment, and the per-day create limit) uses a business day.
32	 */
33	@Component
34	public class BusinessDayResolver {
35	
36	    /**
37	     * Roll {@code date} forward to a business day.
38	     *
39	     * @param date the date to resolve
40	     * @return {@code date} itself when it is a weekday, otherwise the next Monday
41	     */
42	    public LocalDate toBusinessDay(LocalDate date) {
43	        DayOfWeek dayOfWeek = date.getDayOfWeek();
44	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
45	            return date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
46	        }
47	        return date;
48	    }
49	}
