16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Locale;
19	
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where
24	 * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} the
25	 * upper-cased first three letters of the last name and {@code NNNN} is a per-city,
26	 * four-digit zero-padded sequence number (e.g. {@code SYD-SMI-0007}).
27	 */
28	@Component
29	public class CustomerCodeGenerator {
30	
31	    private static final int PREFIX_LENGTH = 3;
32	
33	    /**
34	     * Build the customer code for an owner.
35	     *
36	     * @param city     the owner's city; its first three letters form the leading prefix
37	     * @param lastName the owner's last name; its first three letters form the second prefix
38	     * @param sequence the per-city sequence number placed in the code (zero-padded to four digits)
39	     * @return the formatted customer code, e.g. {@code SYD-SMI-0007}
40	     */
41	    public String generate(String city, String lastName, long sequence) {
42	        return String.format("%s-%s-%04d", prefix(city), prefix(lastName), sequence);
43	    }
44	
45	    private String prefix(String value) {
46	        String upper = value.toUpperCase(Locale.ROOT);
47	        return upper.substring(0, Math.min(PREFIX_LENGTH, upper.length()));
48	    }
49	}
